import { useState } from "react";
import { Box, Button, Popover } from "@mui/material";

const COLORS = ["#1b1b1b", "#FF5733", "#33FF57", "#3357FF", "#F3FF33", "#FF33A8", "#33FFF3"];

const MangeLayout = () => {
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedColor, setSelectedColor] = useState(COLORS[0]);

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = (color) => {
    setAnchorEl(null);
    if (color) {
      setSelectedColor(color);
      document.documentElement.style.setProperty("--main-bg", color);
    }
  };

  return (
    <Box sx={{ textAlign: "center", mt: 3 }}>
      {/* Button to open the color palette */}
      <Button variant="contained" onClick={handleClick} sx={{ backgroundColor: selectedColor }}>
        Open Color Palette
      </Button>

      {/* Popover for color selection */}
      <Popover
        open={Boolean(anchorEl)}
        anchorEl={anchorEl}
        onClose={() => handleClose()}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
        transformOrigin={{ vertical: "top", horizontal: "center" }}
      >
        <Box sx={{ display: "flex", gap: 2, p: 2 }}>
          {COLORS.map((color, index) => (
            <Box
              key={index}
              onClick={() => handleClose(color)}
              sx={{
                width: 30,
                height: 30,
                borderRadius: "50%",
                backgroundColor: color,
                cursor: "pointer",
                border: "2px solid #fff",
                transition: "transform 0.2s",
                "&:hover": { transform: "scale(1.2)" },
              }}
            />
          ))}
        </Box>
      </Popover>
    </Box>
  );
};

export default MangeLayout;
